235	    @Override
236	    @Transactional
237	    public void saveOwner(Owner owner) throws DataAccessException {
238	        if (owner.isNew() && ownerRepository.existsByTelephone(owner.getTelephone())) {
239	            throw new DuplicateTelephoneException(owner.getTelephone());
240	        }
241	        if (owner.isNew()) {
242	            List<Owner> householdMembers = findHouseholdMembers(owner);
243	            if (!householdMembers.isEmpty()) {
244	                if (!owner.isSharesHousehold()) {
245	                    throw new DuplicateHouseholdException(owner.getLastName(), owner.getAddress());
246	                }
247	                owner.setHouseholdId(resolveHouseholdId(householdMembers));
248	            }
249	        }
250	        if (owner.getRegistrationDate() == null) {
251	            owner.setRegistrationDate(LocalDate.now());
252	        }
253	        if (owner.isNew() && owner.getCustomerCode() == null) {
254	            owner.setCustomerCode(generateCustomerCode(owner));
255	        }
256	        ownerRepository.save(owner);
257	
258	    }
259	
260	    /**
261	     * Find the owners that already belong to the same household as {@code owner}, i.e. have the same
262	     * last name and the same address. Both values are compared case-insensitively with collapsed
263	     * whitespace, so differences in letter case or runs of spaces are ignored. Returns an empty list
264	     * when the owner has no last name or address to match on.
265	     */
266	    private List<Owner> findHouseholdMembers(Owner owner) {
267	        String lastName = normalizeHouseholdKey(owner.getLastName());
268	        String address = normalizeHouseholdKey(owner.getAddress());
269	        if (lastName == null || address == null) {
270	            return List.of();
271	        }
272	        return ownerRepository.findAll().stream()
273	            .filter(existing -> lastName.equals(normalizeHouseholdKey(existing.getLastName()))
274	                && address.equals(normalizeHouseholdKey(existing.getAddress())))
275	            .toList();
276	    }
277	
278	    /**
279	     * Resolve the stable {@code householdId} shared by a household. If any existing member already
280	     * carries one it is reused so the identifier stays stable as further owners join; otherwise a
281	     * new one is generated. The resolved value is back-filled onto every member that is missing it
282	     * (or has a different one) so all members of the household share the same identifier.
283	     */
284	    private String resolveHouseholdId(List<Owner> members) {
285	        String householdId = members.stream()
286	            .map(Owner::getHouseholdId)
287	            .filter(id -> id != null && !id.isBlank())
288	            .findFirst()
289	            .orElseGet(() -> UUID.randomUUID().toString());
290	        for (Owner member : members) {
291	            if (!householdId.equals(member.getHouseholdId())) {
292	                member.setHouseholdId(householdId);
293	                ownerRepository.save(member);
294	            }
295	        }
296	        return householdId;
297	    }
298	
299	    /**
300	     * Normalize a value for case-insensitive, whitespace-insensitive household comparison by
301	     * trimming, collapsing internal runs of whitespace to a single space and lower-casing it.
302	     */
303	    private String normalizeHouseholdKey(String value) {
304	        return value == null ? null : value.trim().replaceAll("\\s+", " ").toLowerCase();
305	    }
306	
307	    /**
308	     * Build an owner's {@code customerCode} as {@code '<LAST3>-<NNNN>'}: LAST3 is the
309	     * upper-cased first three letters of the owner's last name, and NNNN is a global
310	     * 4-digit zero-padded sequence equal to one more than the current number of owners
311	     * (e.g. {@code 'SMI-0007'}).
312	     */
313	    private String generateCustomerCode(Owner owner) {
314	        String lastName = owner.getLastName();
315	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
316	        long sequence = ownerRepository.findAll().size() + 1L;
317	        return String.format("%s-%04d", last3, sequence);
318	    }
319	
320	    @Override
