332	    @Override
333	    @Transactional(readOnly = true)
334	    public List<Specialty> findSpecialtiesByNameIn(Set<String> names) {
335	        return findEntityById(() -> specialtyRepository.findSpecialtiesByNameIn(names));
336	    }
337	
338	    private <T> T findEntityById(Supplier<T> supplier) {
339	        try {
340	            return supplier.get();
341	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
342	            // Just ignore not found exceptions for Jdbc/Jpa realization
343	            return null;
344	        }
345	    }
346	
347	}
